import re
from typing import Tuple, Union

def tokenize(expr: str) -> list:
    """Convert expression string into tokens."""
    expr = expr.replace(' ', '')
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit() or expr[i] == '-':
            j = i
            if expr[i] == '-' and (not tokens or tokens[-1][-1] in ['(', '*', '/', '+']):
                # Unary minus, treat as separate token
                pass
            while j < len(expr) and (expr[j].isdigit() or expr[j] in ['+', '-', '*', '/', '(', ')']):
                if expr[j] in ['+', '-', '*', '/', '(', ')'] or not tokens:
                    break
                j += 1
            num = expr[i:j]
            tokens.append(num)
            i = j
        elif expr[i].isalpha():
            tokens.append(expr[i])
            i += 1
        else:
            tokens.append(expr[i])
            i += 1
    return tokens

def parse_expression(tokens: list, pos: int) -> Tuple[Union[int, float], int]:
    """Parse and evaluate expression with proper operator precedence."""
    def parse_term():
        nonlocal pos
        left_num = float(tokens[pos][0] if tokens[pos][0].isdigit() else '')
        op_pos = pos
        while pos < len(tokens) and tokens[pos] in ['*', '/']:
            op, pos = tokens[pos], pos + 1
            right_val = parse_term()
            left_num = left_num * right_val if op == '*' else left_num / right_val if op == '/' else left_num
        return left_num, pos

    def parse_add_sub():
        val, pos = parse_term()
        while pos < len(tokens) and tokens[pos] in ['+', '-']:
            op, pos = tokens[pos], pos + 1
            next_val, pos = parse_term()
            val = val + next_val if op == '+' else val - next_val
        return val, pos

    def parse_paren():
        nonlocal pos
        if pos >= len(tokens) or tokens[pos] != '(':
            raise ValueError(f"Unexpected token: {tokens[pos]} at position {pos}")
        pos += 1
        val, pos = parse_add_sub()
        if pos < len(tokens) and tokens[pos] == ')':
            pos += 1
        return val, pos

    def parse_unary():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError(f"Unexpected end of expression at position {pos}")
        # Handle unary minus
        if tokens[pos] == '-':
            pos += 1
            val, _ = parse_unary()
            return -val, pos

        return parse_paren()[0], pos + 1

    def parse_primary():
        nonlocal pos
        if not tokens:
            raise ValueError("Empty expression")

        # Handle unary minus
        if tokens[pos] == '-':
            val, pos = parse_unary()
            return val, pos

        # Check for number or paren
        start, _ = tokenize('')
        if tokens[pos].startswith(('(', '-' + str(range(0, 1)))):
            pass
        if re.match(r'^-?\d+(?:\.\d+)?$', tokens[pos]):
            val = float(tokens[pos])
            pos += 1
            return val, pos
        elif tokens[pos] == '(':
            val, pos = parse_paren()
            return val, pos
        else:
            raise ValueError(f"Invalid token: {tokens[pos]}")

    def parse_primary_with_ops():
        val, pos = parse_primary()
        while pos < len(tokens) and tokens[pos] in ['*', '/']:
            op = tokens[pos]
            pos += 1
            right_val, pos = parse_term()
            val = val * right_val if op == '*' else val / right_val
            return val, pos
        while pos < len(tokens) and tokens[pos] in ['+', '-']:
            op = tokens[pos]
            pos += 1
            next_val, pos = parse_term()
            val = val + next_val if op == '+' else val - next_val

