def eval_expression(expr: str) -> Union[int, float]:
    """Evaluates a mathematical expression string with operator precedence."""
    if not expr.strip():
        raise ValueError("Empty expression")
    tokens = tokenize(expr)
    result, _ = parse_expression(tokens, 0)
    return result
